; ---- title screen ship selection (-DTITLESEL) --------------------------------------------------------------
; Lives in the zero tail of the music file (&6E21-&6FFF), which is only in memory while the two title screens
; run (loadNotMusique swaps NOTMUSIC.BIN back in). COMMONXX reaches it through the jump table below.
; Left and right cursor keys (raw keyboard rows, joystick too) step the ship shown; splash2Shipnr holds the index
; (bits 0-2) and, in bit 7, "an arrow key was already down" so a held key steps once.
 IFDEF TITLESEL
setCommandsCPL equ 0xC431
setCommandsNOP equ 0xC435
transferBuffertoScreen equ 0x1ED1
spawnCommandParser equ 0x809C
dataFromPPI equ 0x8D11
splash2Shipnr equ 0x1DA8
printString equ 0xC2DC
charXY equ 0x38C4
flagWhichScreenToPrint equ 0xC44E
todoPrintFlag3948 equ 0x3948
todoSomePrintFlag equ 0x3949
    ASSERT $ == 0x6E21
    jp titleScreen2                 ; +0  replaces call transferBuffertoScreen (press-space screen)
    jp titleNext                    ; +3  replaces the automatic ship pick before the press-space screen
    jp titleName                    ; +6  replaces printELITE on the press-space screen
titleScreen2:
    call titleArrows
    jp transferBuffertoScreen
; The press-space screen opens with the Cobra Mk III, as the first screen does
titleNext:
    ld hl,splash2Shipnr
    ld a,(hl)
    and 0x80                        ; keep "key is down"
    or 2                            ; always start on the Cobra Mk III (index 2)
    ld (hl),a
    jr titleShow
; Step the ship on a fresh left or right press. The raw PPI rows are read because irki2 rewrites keybFlags2 into roll values.
; Active low: row 0 bit 1 cursor right, row 1 bit 0 cursor left, row 9 bits 2 and 3 joystick left and right.
titleArrows:
    ld hl,dataFromPPI
    ld a,(hl)
    cpl
    and 0x02
    ld c,a
    inc hl
    ld a,(hl)
    cpl
    and 0x01
    or c
    ld c,a
    ld a,(dataFromPPI + 9)
    cpl
    rra
    rra
    or c
    and 0x03                        ; bit 0 left, bit 1 right
    ld c,a
    ld hl,splash2Shipnr
    jr z,titleKeyUp
    bit 7,(hl)
    ret nz
    set 7,(hl)
    ld a,(hl)
    srl c                           ; carry = left
    jr c,titleLeft
    inc a
    jr titleStep
titleLeft:
    dec a
titleStep:
    and 0x07
    or 0x80                         ; keep "key is down" (a wrap from 0 to 7 would otherwise clear it)
    ld (hl),a
; Spawn the demo ship for the current index (the command patches go to NOP for the spawn and back to CPL after it)
titleShow:
    call setCommandsNOP
    ld a,(splash2Shipnr)
    and 0x07
    ld e,a
    ld d,0
    ld hl,titleShips
    add hl,de
    ld a,(hl)
    call spawnCommandParser
    jp setCommandsCPL
titleKeyUp:
    res 7,(hl)
    ret
; Print the current ship's name centred on the title line (text row 1), where the ELITE title stood
titleName:
    ld a,(splash2Shipnr)
    and 0x07
    add a,a
    add a,a
    add a,a
    add a,a                         ; 16 bytes per name
    ld e,a
    ld d,0
    ld hl,titleNames
    add hl,de
    push hl
    ld b,0
titleNameLen:
    ld a,(hl)
    and a
    jr z,titleNameCentre
    inc hl
    inc b
    jr titleNameLen
titleNameCentre:
    ld a,30
    sub b
    srl a                           ; charXY is incremented before each character is drawn
    ld l,a
    ld h,1
    ld (charXY),hl
    ld hl,flagWhichScreenToPrint
    set 7,(hl)
    pop hl
    ld a,(todoPrintFlag3948)
    push af
    ld a,1                          ; capitals only
    ld (todoPrintFlag3948),a
titleNamePrint:
    ld a,(hl)
    and a
    jr z,titleNameEnd
    push hl
    call printString
    pop hl
    inc hl
    jr titleNamePrint
titleNameEnd:
    ld hl,0xA000 + 2 * 0x0100 + 2   ; text row 1, column 1 of the bitmap buffer: 8 pixel lines, 0x40 bytes apart
    ld c,8
titleNameLine:
    ld b,60                         ; columns 1-30
titleNameBlue:
    ld a,(hl)                       ; background is pen 1 (low nibble 1111), text pen 0 (both planes clear); ship lines (pen 3) must stay
    ld e,a
    rrca
    rrca
    rrca
    rrca
    or e
    cpl
    and 0x0F                        ; pixels with both planes clear = text
    ld d,a
    rlca
    rlca
    rlca
    rlca
    or d
    or e                            ; text becomes pen 3, the pen of the ship lines and the frame; everything else is unchanged
    ld (hl),a
    inc hl
    djnz titleNameBlue
    ld de,0x40 - 60
    add hl,de
    dec c
    jr nz,titleNameLine
    pop af
    ld (todoPrintFlag3948),a
    ld a,1                          ; the next letter, 'Press', is a capital
    ld (todoSomePrintFlag),a
    ld hl,flagWhichScreenToPrint
    res 7,(hl)
    ret
; spawnCommandParser actions: ship type in the high nibble, action 9 (title ship) in the low one
titleShips:
    db 0x69                         ; Viper
    db 0xB9                         ; Asp Mk II
    db 0x79                         ; Cobra Mk III (index 2 is where splash2Shipnr starts)
    db 0xC9                         ; Fer-de-Lance
    db 0xE9                         ; Sidewinder
    db 0xF9                         ; Krait
    db 0x59                         ; Rock Hermit (the Python is too long for the window)
    db 0xD9                         ; Thargoid
; Ship names in the order of titleShips, zero-terminated, 16 bytes each
titleNames:
    db "VIPER",0
    ds 16 - 6
    db "ASP MK II",0
    ds 16 - 10
    db "COBRA MK III",0
    ds 16 - 13
    db "FER-DE-LANCE",0
    ds 16 - 13
    db "SIDEWINDER",0
    ds 16 - 11
    db "KRAIT",0
    ds 16 - 6
    db "ROCK HERMIT",0
    ds 16 - 12
    db "THARGOID",0
    ds 16 - 9
    ASSERT $ <= 0x7000
    ds 0x7000 - $
 ELSE
    ds 0x7000 - $
 ENDIF
